1	import {BEAT_FRAMES, CREED_SNAP_BEAT, FRAME_COUNT, OPEN_SNAP_BEAT, PAGES, frameState} from './timeline.js';
2	import {MOTTO, SCRIPT} from './script.js';
3	
4	const W = 1920, H = 1080;
5	const DARK = '#0E0D0B', SHADE = '#1A1816', INK2 = '#2A2723', DEEP = '#4B4541', FOG = '#8A8681', MIST = '#C4BFBA', LIGHT = '#FAF6F2';
6	const ACCENT = '#FD602A', ACCENT_TOP = '#F3815A', ACCENT_SIDE = '#BE3D24', RED = '#A9321B';
7	const SONG = '"Songti SC"';
8	const font = (size, weight = 400) => `${weight} ${size}px ${SONG}`;
9	const MONO = size => `400 ${size}px Menlo`;
10	const DIN = size => `700 ${size}px "DIN Condensed"`;
11	const LEFT = 150, SAFE_L = 80, SAFE_R = W - 80;
12	const NARR = font(44), NARR_SPACING = '5px';
13	
14	const clamp = (v, a = 0, b = 1) => Math.max(a, Math.min(b, v));
15	const lerp = (a, b, t) => a + (b - a) * t;
16	const ease = x => (x < 0.5 ? 4 * x ** 3 : 1 - (-2 * x + 2) ** 3 / 2);
17	const out = x => 1 - (1 - x) ** 3;
18	const inQ = x => x * x * x;
19	const seg = (b, b0, b1) => clamp((b - b0) / (b1 - b0));
20	// 落下后带一次回弹
21	const drop = x => (x < 0.7 ? (x / 0.7) ** 2 : 1 - 0.06 * Math.sin(Math.PI * (x - 0.7) / 0.3));
22	
23	function rng(seed) {
24	  return () => {
25	    seed |= 0; seed = (seed + 0x6d2b79f5) | 0;
26	    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
27	    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
28	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
29	  };
30	}
31	
32	const stage = document.getElementById('stage');
33	const ctx = stage.getContext('2d');
34	const canvas = (w = W, h = H) => Object.assign(document.createElement('canvas'), {width: w, height: h});
35	
36	function report(message) {
37	  if (!window.renderErrors.includes(message)) window.renderErrors.push(message);
38	}
39	
40	// ---------- 底：暗场、顶部聚光、暗角、浮尘、胶片颗粒 ----------
41	
42	function makeGround() {
43	  const c = canvas();
44	  const g = c.getContext('2d');
45	  g.fillStyle = DARK; g.fillRect(0, 0, W, H);
46	  const spot = g.createRadialGradient(W * 0.45, -160, 60, W * 0.45, -160, 1300);
47	  spot.addColorStop(0, 'rgba(250,240,225,0.11)');
48	  spot.addColorStop(1, 'rgba(250,240,225,0)');
49	  g.fillStyle = spot; g.fillRect(0, 0, W, H);
50	  const v = g.createRadialGradient(W / 2, H / 2, 420, W / 2, H / 2, 1150);
51	  v.addColorStop(0, 'rgba(0,0,0,0)');
52	  v.addColorStop(1, 'rgba(0,0,0,0.55)');
53	  g.fillStyle = v; g.fillRect(0, 0, W, H);
54	  return c;
55	}
56	
57	function makeGrain() {
58	  const c = canvas(512, 512);
59	  const g = c.getContext('2d');
60	  const img = g.createImageData(512, 512);
61	  const r = rng(7);
62	  for (let i = 0; i < img.data.length; i += 4) {
63	    const v = r() > 0.5 ? 255 : 0;
64	    img.data[i] = img.data[i + 1] = img.data[i + 2] = v;
65	    img.data[i + 3] = r() * 16;
66	  }
67	  g.putImageData(img, 0, 0);
68	  return c;
69	}
70	
71	// 雾：模糊的随机团块，横向可平铺
72	function makeFog(seed) {
73	  const c = canvas(2400, 700);
74	  const g = c.getContext('2d');
75	  const r = rng(seed);
76	  g.filter = 'blur(40px)';
77	  for (let i = 0; i < 90; i++) {
78	    const x = r() * 2400, y = 150 + r() * 400, rad = 80 + r() * 220;
79	    for (const dx of [-2400, 0, 2400]) {
80	      const grad = g.createRadialGradient(x + dx, y, 0, x + dx, y, rad);
81	      grad.addColorStop(0, `rgba(200,194,186,${0.08 + r() * 0.1})`);
82	      grad.addColorStop(1, 'rgba(200,194,186,0)');
83	      g.fillStyle = grad; g.fillRect(x + dx - rad, y - rad, rad * 2, rad * 2);
84	    }
85	  }
86	  return c;
87	}
88	
89	// 电路板底纹：只有横竖走线和过孔，不仿任何真实电路
90	function makeCircuit() {
91	  const c = canvas();
92	  const g = c.getContext('2d');
93	  const r = rng(31);
94	  g.strokeStyle = '#2C2825'; g.lineWidth = 2; g.fillStyle = '#2C2825';
95	  for (let i = 0; i < 120; i++) {
96	    let x = Math.round(r() * 48) * 40, y = Math.round(r() * 27) * 40;
97	    g.beginPath(); g.moveTo(x, y);
98	    for (let k = 0; k < 4; k++) {
99	      if (r() > 0.5) x += (r() > 0.5 ? 1 : -1) * Math.round(1 + r() * 5) * 40;
100	      else y += (r() > 0.5 ? 1 : -1) * Math.round(1 + r() * 4) * 40;
101	      g.lineTo(x, y);
102	    }
103	    g.stroke();
104	    g.beginPath(); g.arc(x, y, 4, 0, Math.PI * 2); g.fill();
105	  }
106	  return c;
107	}
108	
109	// 收尾两页的米白纸面：中心略亮、四周略暗。全片只在这里翻转一次亮暗。
110	const PAPER = '#F6F3EB', INK = '#070300', PAPER_PAGES = new Set(['ours', 'end']);
111	function makePaper() {
112	  const c = canvas();
113	  const g = c.getContext('2d');
114	  g.fillStyle = PAPER; g.fillRect(0, 0, W, H);
115	  const v = g.createRadialGradient(W / 2, H / 2, 300, W / 2, H / 2, 1200);
116	  v.addColorStop(0, 'rgba(255,255,255,0.16)');
117	  v.addColorStop(1, 'rgba(90,70,40,0.12)');
118	  g.fillStyle = v; g.fillRect(0, 0, W, H);
119	  return c;
120	}
121	const GROUND = makeGround(), PAPER_GROUND = makePaper(), GRAIN = makeGrain(), FOG_A = makeFog(3), FOG_B = makeFog(9), CIRCUIT = makeCircuit();
122	const DUST = (() => {
123	  const r = rng(77);
124	  return Array.from({length: 150}, () => ({x: r() * W, y: r() * H, z: 0.3 + r() * 0.7, p: r() * 6.28}));
125	})();
126	
127	function dust(g, n, amount = 1) {
128	  for (const d of DUST) {
129	    const x = (d.x + n * 0.25 * d.z) % W, y = (d.y + n * 0.12 * d.z + Math.sin(n * 0.02 + d.p) * 8) % H;
130	    g.globalAlpha = amount * (0.12 + 0.3 * d.z) * (0.7 + 0.3 * Math.sin(n * 0.05 + d.p));
131	    g.fillStyle = LIGHT;
132	    g.fillRect(x, y, 1.2 + 1.8 * d.z, 1.2 + 1.8 * d.z);
133	  }
134	  g.globalAlpha = 1;
135	}
136	
137	function grain(g, n) {
138	  const r = rng(n + 1);
139	  const ox = Math.floor(r() * 512), oy = Math.floor(r() * 512);
140	  g.globalCompositeOperation = 'overlay';
141	  for (let y = -oy; y < H; y += 512) for (let x = -ox; x < W; x += 512) g.drawImage(GRAIN, x, y);
142	  g.globalCompositeOperation = 'source-over';
143	}
144	
145	// ---------- 文字 ----------
146	
147	function setFont(g, f, spacing = '0px') {
148	  g.font = f; g.letterSpacing = spacing; g.textBaseline = 'alphabetic';
149	}
150	
151	function text(g, str, x, y, f, color, align = 'left', spacing = '0px') {
152	  setFont(g, f, spacing);
153	  g.fillStyle = color; g.textAlign = align;
154	  const w = g.measureText(str).width;
155	  const x0 = align === 'left' ? x : align === 'right' ? x - w : x - w / 2;
156	  if (x0 < SAFE_L - 1 || x0 + w > SAFE_R + 1) report(`超出安全区：${str}`);
157	  g.fillText(str, x, y);
158	  g.letterSpacing = '0px';
159	  return w;
160	}
161	
162	// 逐字出现，每字 3 帧（0.1 秒），从 line.at 指定的拍点起打。
163	function shown(line, s) {
164	  const start = Math.round(line.at * BEAT_FRAMES);
165	  if (s.local < start) return '';
166	  const chars = [...line.text];
167	  return chars.slice(0, Math.min(chars.length, Math.floor((s.local - start) / 3) + 1)).join('');
168	}
169	
170	function typed(g, line, s, x, y, f = NARR, color = LIGHT, align = 'left', spacing = NARR_SPACING) {
171	  const str = shown(line, s);
172	  if (!str) return 0;
173	  setFont(g, f, spacing);
174	  const full = g.measureText(line.text).width;
175	  const x0 = align === 'right' ? x - full : x;
176	  if (x0 < SAFE_L || x0 + full > SAFE_R) report(`超出安全区：${line.text}`);
177	  g.fillStyle = color; g.textAlign = align;
178	  g.fillText(align === 'right' ? line.text.slice(0, str.length) : str, x, y);
179	  g.letterSpacing = '0px';
180	  return full;
181	}
182	
183	// 文字崩塌：每个字带一点旋转向下坠落，t 从 0 到 1
184	function collapse(g, str, x, y, f, color, t, seed, spacing = NARR_SPACING) {
185	  setFont(g, f, spacing);
186	  g.textAlign = 'left';
187	  const r = rng(seed);
188	  let cx = x;
189	  for (const ch of str) {
190	    const w = g.measureText(ch).width;
191	    const delay = r() * 0.35, k = clamp((t - delay) / (1 - delay));
192	    g.save();
193	    g.translate(cx + w / 2, y + 900 * inQ(k));
194	    g.rotate((r() - 0.5) * 1.6 * k);
195	    g.globalAlpha = 1 - k * 0.8;
196	    g.fillStyle = color;
197	    g.fillText(ch, -w / 2, 0);
198	    g.restore();
199	    cx += w;
200	  }
201	  g.letterSpacing = '0px';
202	}
203	
204	function narration(g, line, s, x, y, endFall, seed, f = NARR, color = LIGHT) {
205	  if (s.b >= endFall) collapse(g, line.text, x, y, f, color, seg(s.b, endFall, endFall + 1.6), seed);
206	  else typed(g, line, s, x, y, f, color);
207	}
208	
209	function corner(g, lines, alpha = 1) {
210	  g.save();
211	  g.globalAlpha = alpha;
212	  text(g, lines[0].text, SAFE_R, 78, font(24), MIST, 'right');
213	  text(g, lines[1].text, SAFE_R, 110, MONO(19), FOG, 'right');
214	  g.strokeStyle = FOG; g.lineWidth = 1;
215	  g.beginPath(); g.moveTo(SAFE_R - 46, 126); g.lineTo(SAFE_R, 126); g.stroke();
216	  g.restore();
217	}
218	
219	function source(g, line) {
220	  text(g, line.text, LEFT, 1030, font(18), DEEP);
221	}
222	
223	function demo(g, line, x, y, align = 'right') {
224	  text(g, line.text, x, y, font(20), DEEP, align);
225	}
226	
227	// 手绘红圈：抖动的椭圆，按进度画出
228	function redCircle(g, cx, cy, rx, ry, k, seed) {
229	  if (k <= 0) return;
230	  const r = rng(seed);
231	  const wob = Array.from({length: 9}, () => r());
232	  g.save();
233	  g.strokeStyle = RED; g.lineWidth = 5; g.lineCap = 'round';
234	  g.beginPath();
235	  const total = Math.PI * 2.15 * k;
236	  for (let a = 0; a <= total; a += 0.05) {
237	    const j = 1 + 0.05 * Math.sin(a * 3 + wob[0] * 6) + 0.03 * Math.sin(a * 7 + wob[1] * 6);
238	    const x = cx + rx * j * Math.cos(a - 2.4), y = cy + ry * j * Math.sin(a - 2.4) + a * 2;
239	    a === 0 ? g.moveTo(x, y) : g.lineTo(x, y);
240	  }
241	  g.stroke();
242	  g.restore();
243	}
244	
245	function frameBox(g, x, y, w, h, k) {
246	  if (k <= 0) return;
247	  g.strokeStyle = FOG; g.lineWidth = 1.5;
248	  const p = 2 * (w + h) * k;
249	  g.beginPath(); g.moveTo(x, y);
250	  const pts = [[x + w, y], [x + w, y + h], [x, y + h], [x, y]];
251	  let left = p, cx = x, cy = y;
252	  for (const [px, py] of pts) {
253	    const d = Math.hypot(px - cx, py - cy);
254	    if (left >= d) { g.lineTo(px, py); left -= d; cx = px; cy = py; }
255	    else { g.lineTo(cx + (px - cx) * left / d, cy + (py - cy) * left / d); break; }
256	  }
257	  g.stroke();
258	}
259	
260	// ---------- 由字形均匀取点 ----------
261	
262	function glyphPoints(rows, size, count, seed, accentFrom = -1) {
263	  const c = canvas();
264	  const g = c.getContext('2d');
265	  g.font = font(size, 900); g.fillStyle = '#000'; g.textBaseline = 'alphabetic';
266	  const boxes = [];
267	  for (const {str, x, y} of rows) {
268	    let cx = x;
269	    for (const ch of str) {
270	      const w = g.measureText(ch).width;
271	      g.fillText(ch, cx, y);
272	      boxes.push({x0: cx, x1: cx + w, y0: y - size, y1: y + size * 0.2});
273	      cx += w;
274	    }
275	  }
276	  const data = g.getImageData(0, 0, W, H).data;
277	  let pts = [];
278	  for (let step = 14; step >= 2 && pts.length < count; step--) {
279	    pts = [];
280	    for (let y = 0; y < H; y += step) for (let x = (y / step % 2) * step / 2; x < W; x += step) if (data[(y * W + Math.round(x)) * 4 + 3] > 140) pts.push({x: Math.round(x), y});
281	  }
282	  if (pts.length < count) throw new Error(`字形取点不足：${pts.length} < ${count}`);
283	  const picked = Array.from({length: count}, (_, i) => pts[Math.floor(i * pts.length / count)]);
284	  const r = rng(seed);
285	  for (let i = picked.length - 1; i > 0; i--) { const j = Math.floor(r() * (i + 1)); [picked[i], picked[j]] = [picked[j], picked[i]]; }
286	  const acc = accentFrom >= 0 ? boxes.slice(accentFrom, accentFrom + 2) : [];
287	  return picked.map(p => ({...p, accent: acc.some(bx => p.x >= bx.x0 && p.x < bx.x1 && p.y >= bx.y0 && p.y <= bx.y1)}));
288	}
289	
290	function scatter(n, seed, box) {
291	  const r = rng(seed);
292	  return Array.from({length: n}, () => ({x: lerp(box[0], box[2], r()), y: lerp(box[1], box[3], r()), d: r()}));
293	}
294	
295	const L = {
296	  name: {size: 260, x: 250, y: 600},
297	  creed: {size: 150, x: LEFT, y: 680},
298	  drones: {size: 190, x: 900, y: [450, 690]},
299	  year: {size: 440, x: 110, y: 660},
300	  word: {size: 112, x: LEFT, y: 560},
301	};
302	let P = {};
303	function prepare() {
304	  P.name = glyphPoints([{str: SCRIPT.open.name.text, x: L.name.x, y: L.name.y}], L.name.size, 1700, 3);
305	  P.nameFrom = scatter(P.name.length, 21, [0, 0, 1, 1]);
306	  P.creed = glyphPoints([{str: MOTTO.text, x: L.creed.x, y: L.creed.y}], L.creed.size, 1700, 5, 7);
307	  P.creedFrom = scatter(P.creed.length, 22, [80, 150, 1840, 980]);
308	  P.drones = glyphPoints(MOTTO.lines.map((str, i) => ({str, x: L.drones.x, y: L.drones.y[i]})), L.drones.size, 2026, 9, 6);
309	  P.dronesFrom = scatter(P.drones.length, 23, [760, H + 20, 1800, H + 280]);
310	  P.year = glyphPoints([{str: SCRIPT.y1979.year.text, x: L.year.x, y: L.year.y}], L.year.size, 900, 13);
311	  P.yearFall = scatter(P.year.length, 29, [-1, 0, 1, 1]);
312	  P.words = SCRIPT.plan.words.map((w, i) => glyphPoints([{str: w.text, x: L.word.x, y: L.word.y}], L.word.size, 1100, 40 + i));
313	  P.wordsFrom = scatter(1100, 24, [60, 380, 1300, 1000]);
314	  P.yearMask = canvas();
315	  const mg = P.yearMask.getContext('2d');
316	  mg.font = font(L.year.size, 900); mg.textBaseline = 'alphabetic'; mg.fillStyle = '#000';
317	  mg.fillText(SCRIPT.y1979.year.text, L.year.x, L.year.y);
318	  P.work = canvas();
319	}
320	
321	// 点阵：从起点飞向字形，t 为 0–1
322	function cloud(g, pts, from, t, size, color, accent = ACCENT, delay = 0.4) {
323	  for (let i = 0; i < pts.length; i++) {
324	    const p = pts[i], f = from[i % from.length];
325	    const k = ease(clamp((t - f.d * delay) / (1 - delay)));
326	    g.globalAlpha = 0.35 + 0.65 * k;
327	    g.fillStyle = p.accent ? accent : color;
328	    g.fillRect(lerp(f.x, p.x, k) - size / 2, lerp(f.y, p.y, k) - size / 2, size, size);
329	  }
330	  g.globalAlpha = 1;
331	}
332	
333	// 点阵散开下落，t 为 0–1
334	function rain(g, pts, t, size, color, seed) {
335	  const r = rng(seed);
336	  for (const p of pts) {
337	    const d = r() * 0.5, k = clamp((t - d) / (1 - d)), drift = (r() - 0.5) * 60;
338	    if (k <= 0) { g.globalAlpha = 1; g.fillStyle = color; g.fillRect(p.x - size / 2, p.y - size / 2, size, size); continue; }
339	    g.globalAlpha = 0.9 * (1 - k);
340	    g.fillStyle = p.accent ? ACCENT : color;
341	    g.fillRect(p.x + drift * k, p.y + 520 * inQ(k), size * 0.8, size * (1 + 3 * k));
342	  }
343	  g.globalAlpha = 1;
344	}
345	
346	// ---------- 物件 ----------
347	
348	// 橙色方块，正面白字，顶面受光、侧面背光、下方短软投影
349	function cube(g, x, y, s, ch, dim = 0, glow = 0) {
350	  const d = s * 0.2;
351	  // dim 为 0–1：方块向暗红褐退色，用于“关灯”后的其余方块
352	  const mix = (c, k) => {
353	    const a = [1, 3, 5].map(i => parseInt(c.slice(i, i + 2), 16)), t = [42, 35, 32];
354	    return `rgb(${a.map((v, i) => Math.round(lerp(v, t[i], 0.8 * k))).join(',')})`;
355	  };
356	  g.save();
357	  g.fillStyle = 'rgba(0,0,0,0.45)';
358	  g.beginPath(); g.ellipse(x + s * 0.55, y + s + 10, s * 0.62, s * 0.12, 0, 0, Math.PI * 2); g.fill();
359	  if (glow) { g.shadowColor = ACCENT; g.shadowBlur = 40 * glow; }
360	  g.fillStyle = mix(ACCENT, dim); g.fillRect(x, y, s, s);
361	  g.shadowBlur = 0;
362	  g.fillStyle = mix(ACCENT_TOP, dim);
363	  g.beginPath(); g.moveTo(x, y); g.lineTo(x + d, y - d); g.lineTo(x + s + d, y - d); g.lineTo(x + s, y); g.fill();
364	  g.fillStyle = mix(ACCENT_SIDE, dim);
365	  g.beginPath(); g.moveTo(x + s, y); g.lineTo(x + s + d, y - d); g.lineTo(x + s + d, y + s - d); g.lineTo(x + s, y + s); g.fill();
366	  g.fillStyle = dim > 0 ? `rgba(250,246,242,${1 - 0.7 * dim})` : LIGHT;
367	  g.font = font(Math.round(s * 0.74), 900); g.textAlign = 'center'; g.textBaseline = 'alphabetic';
368	  g.fillText(ch, x + s / 2, y + s * 0.8);
369	  g.restore();
370	}
