378	// 无脸剪影：长外套，只有缓慢行走或站立
379	function figure(g, x, y, h, walk, color = '#151311') {
380	  const u = h / 10;
381	  const sw = Math.sin(walk) * u * 0.9;
382	  g.save();
383	  g.fillStyle = color; g.strokeStyle = color; g.lineCap = 'round';
384	  g.beginPath(); g.arc(x, y - 9.1 * u, u * 0.75, 0, Math.PI * 2); g.fill();
385	  g.beginPath();
386	  g.moveTo(x - 0.9 * u, y - 8.1 * u); g.lineTo(x + 0.9 * u, y - 8.1 * u);
387	  g.lineTo(x + 1.5 * u, y - 3 * u); g.lineTo(x - 1.5 * u, y - 3 * u); g.closePath(); g.fill();
388	  g.lineWidth = u * 0.7;
389	  g.beginPath(); g.moveTo(x - 0.5 * u, y - 3.2 * u); g.lineTo(x - 0.5 * u + sw, y);
390	  g.moveTo(x + 0.5 * u, y - 3.2 * u); g.lineTo(x + 0.5 * u - sw, y); g.stroke();
391	  g.restore();
392	  g.strokeStyle = 'rgba(196,191,186,0.35)'; g.lineWidth = 1.5;
393	  g.beginPath(); g.ellipse(x, y + 4, u * 3, u * 0.6, 0, 0, Math.PI * 2); g.stroke();
394	}
