402	  g.shadowColor = color; g.shadowBlur = 12;
403	  g.beginPath();
404	  g.moveTo(-120, 200); g.lineTo(-120, -160);
405	  g.bezierCurveTo(-120, -300, 120, -300, 120, -160);
406	  g.lineTo(120, 200); g.stroke();
407	  g.beginPath(); g.moveTo(-10, -262); g.lineTo(0, -292); g.lineTo(10, -262); g.stroke();
