412	  for (let i = 0; i <= 14; i++) { const y = -130 + i * 17; g.moveTo(-48, y); g.lineTo(48, y + 6); }
413	  g.moveTo(-48, -134); g.lineTo(-48, 112); g.moveTo(48, -128); g.lineTo(48, 118);
