420	    g.strokeStyle = ACCENT; g.lineWidth = 5; g.shadowColor = ACCENT; g.shadowBlur = 30 * glow; g.globalAlpha = glow;
421	    g.beginPath(); g.moveTo(-18, 200); g.lineTo(-18, -110); g.lineTo(0, -126); g.lineTo(18, -110); g.lineTo(18, 200); g.stroke();
