427	const PLAIN_ROW = '国家大事千万尽力'.repeat(14);
428	function plain(g, b, alpha, speed = 0.55) {
429	  const hy = 360, vx = 960;
430	  g.save();
431	  const road = g.createLinearGradient(0, hy, 0, H);
432	  road.addColorStop(0, 'rgba(250,246,242,0.25)');
433	  road.addColorStop(1, 'rgba(250,246,242,0.07)');
434	  g.globalAlpha = alpha;
435	  g.fillStyle = road;
436	  g.beginPath(); g.moveTo(vx - 6, hy); g.lineTo(vx + 6, hy); g.lineTo(vx + 260, H); g.lineTo(vx - 260, H); g.fill();
437	  for (let k = 0; k < 34; k++) {
438	    const z = 1 + ((k * 0.9 - b * speed) % 30.6 + 30.6) % 30.6;
439	    const y = hy + 720 / z;
440	    if (y > H + 40) continue;
441	    const size = Math.max(3, 70 / z);
442	    g.globalAlpha = alpha * clamp(1.2 - z / 26) * 0.9;
443	    g.fillStyle = z < 6 ? DEEP : INK2;
444	    g.font = font(Math.round(size), 700); g.textBaseline = 'alphabetic';
445	    const gap = 280 / z;
446	    g.textAlign = 'right'; g.fillText(PLAIN_ROW, vx - gap, y);
447	    g.textAlign = 'left'; g.fillText(PLAIN_ROW, vx + gap, y);
448	  }
449	  const fog = g.createLinearGradient(0, hy - 30, 0, hy + 120);
450	  fog.addColorStop(0, 'rgba(14,13,11,1)');
451	  fog.addColorStop(1, 'rgba(14,13,11,0)');
452	  g.globalAlpha = 1;
453	  g.fillStyle = fog; g.fillRect(0, hy - 30, W, 150);
454	  g.restore();
455	}
