498	function orbs(g, s, kinds, x0, y0) {
499	  const r = rng(51);
500	  const spots = [];
501	  let row = 0, i = 0;
502	  while (i < kinds.length) {
503	    const n = 12 - row;
504	    for (let c = 0; c < n && i < kinds.length; c++, i++) spots.push({x: x0 + (row * 0.5 + c) * 56 + (r() - 0.5) * 8, y: y0 - row * 50 + (r() - 0.5) * 6});
505	    row++;
506	  }
507	  let landed = 0;
508	  kinds.forEach((kind, k) => {
509	    const start = 30 + k;
510	    const t = clamp((s.local - start) / 14);
511	    if (t <= 0) return;
512	    if (t >= 1) landed++;
513	    const p = spots[k];
514	    const x = lerp(p.x + 220, p.x, t), y = lerp(-80, p.y, drop(t));
515	    const base = {prof: ACCENT, assoc: LIGHT, lect: MIST, staff: DEEP}[kind];
516	    const grad = g.createRadialGradient(x - 9, y - 10, 3, x, y, 27);
517	    grad.addColorStop(0, kind === 'prof' ? ACCENT_TOP : '#FFFFFF');
518	    grad.addColorStop(0.35, base);
519	    grad.addColorStop(1, kind === 'prof' ? ACCENT_SIDE : SHADE);
520	    g.fillStyle = grad;
521	    g.beginPath(); g.arc(x, y, 26, 0, Math.PI * 2); g.fill();
522	  });
523	  return landed;
524	}
