const d = Math.floor(roll), frac = roll - d;
for (const [digit, off] of [[d, -frac], [Math.min(d + 1, 7), 1 - frac]]) {
  g.globalAlpha = 1 - Math.abs(off) * 0.6;
  g.fillText(String(digit), yx + wHead, yy + off * size * 0.8);
}
g.restore();
