    grad.addColorStop(0, kind === 'prof' ? ACCENT_TOP : '#FFFFFF');
    grad.addColorStop(0.35, base);
    grad.addColorStop(1, kind === 'prof' ? ACCENT_SIDE : SHADE);
    g.fillStyle = grad;
    g.beginPath(); g.arc(x, y, rad, 0, Math.PI * 2); g.fill();
  });
  return landed;
}

