import {synthesize} from '../../../蒋葆增的家国情怀/短片/music.mjs';

const {left, right} = synthesize();
const top = [];
for (const [name, ch] of [['L', left], ['R', right]]) {
  for (let i = 1; i < ch.length; i++) {
    const d = Math.abs(ch[i] - ch[i - 1]);
    if (d > 0.3) top.push({name, t: (i / 48000).toFixed(4), d: d.toFixed(3)});
  }
}
top.sort((a, b) => b.d - a.d);
console.log(top.slice(0, 15));

